/* Card set: Insects & Arthropods (generated from the approved roster-final.csv by the Insects build, schema per tools/csv-to-set.js).
   (insects.js exceeds the comfortable push size, so the remaining cards live in
   insects-additions.js, which must stay directly after 'insects.js' in sets/manifest.js.) */
CardSets.register({"id":"insects","name":"Insects & Arthropods","code":"INSE","description":"420 cards of the small and many-legged — butterflies and moths, beetles, bees and ants, dragonflies, spiders and scorpions, mantises and more.","theme":{"primary":"#4e7a27","secondary":"#d98a2b","artBackground":"#f6f3e4","artFit":"cover"},"pack":{"name":"Insects & Arthropods Pack","emblem":"🦋","skin":"insects"},"cards":[{"name":"Monarch Butterfly","rarity":"chase","id":"monarch-butterfly","subtitle":"Butterfly","details":"Famed for its long migration across North America, this orange-and-black butterfly travels thousands of miles between breeding and wintering grounds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monarch%20butterfly%20in%20BBG%20%2884685%29.jpg?width=1024"},{"name":"Queen Alexandra's Birdwing","rarity":"chase","id":"queen-alexandras-birdwing","subtitle":"Butterfly","details":"The world's largest butterfly, with females spanning up to 28 cm, this rare birdwing flies high in the rainforest canopy of eastern Papua New Guinea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/013602428%20Ornithoptera%20alexandrae%20dorsal%20male.jpg?width=1024"},{"name":"Blue Morpho","rarity":"chase","id":"blue-morpho","subtitle":"Butterfly","details":"Its brilliant blue upperwings flash in the sunlight as it flaps through Central and South American rainforests, while the underside stays dull brown.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morpho%20peleides%202.jpg?width=1024"},{"name":"Atlas Moth","rarity":"chase","id":"atlas-moth","subtitle":"Moth","details":"One of the largest moths on Earth, with broad rusty-brown wings tipped with snake-like patterns and a wingspan that can span an adult hand.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atlas%20Moth%20%28Attacus%20atlas%29.jpg?width=1024"},{"name":"Titan Beetle","rarity":"chase","id":"titan-beetle","subtitle":"Beetle","details":"One of the largest beetles in the Amazon rainforest, the titan beetle's powerful jaws and long body make it a giant among longhorn beetles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/TITANUS%20GIGANTEUS.jpg?width=1024"},{"name":"Goliath Beetle","rarity":"chase","id":"goliath-beetle","subtitle":"Beetle","details":"Among the heaviest insects on Earth, Africa's goliath beetles are strong climbers with boldly patterned shells in black, white and chestnut.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2013-03-09%20Goliathk%C3%A4fer%20Goliathus%20goliatus%20anagoria.jpg?width=1024"},{"name":"Hercules Beetle","rarity":"chase","id":"hercules-beetle","subtitle":"Beetle","details":"A giant rhinoceros beetle of Central and South America, males carry a huge curved horn that can make up half of their total body length.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dynastes%20hercules.jpg?width=1024"},{"name":"Death's-head Hawkmoth","rarity":"chase","id":"deaths-head-hawkmoth","subtitle":"Moth","details":"Named for the pale skull-like marking on its thorax, this strong-flying hawkmoth can squeak when handled and hovers deftly at flowers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acherontia%20atropos%20Calceranica%2002.jpg?width=1024"},{"name":"Peacock Spider","rarity":"chase","id":"peacock-spider","subtitle":"Spider","details":"Males of this tiny Australian jumping spider, about 5 mm long, raise a brightly patterned abdominal flap in a courtship dance for females.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/MalePeacockSpider.jpg?width=1024"},{"name":"Giant Golden Orb Weaver","rarity":"chase","id":"giant-golden-orb-weaver","subtitle":"Spider","details":"One of the largest orb weavers, females reach 20 cm across the legs and spin huge golden webs up to 1.5 m wide across Asia and Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Female-Nephila-pilipes.jpg?width=800"},{"name":"Glasswing Butterfly","rarity":"legendary","id":"glasswing-butterfly","subtitle":"Butterfly","details":"Transparent wings edged in brown and orange let this Central American butterfly vanish in the forest shade, confusing predators that hunt by sight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Glasswinged%20butterfly%20%28Greta%20oto%29%20%286727431229%29.jpg?width=1024"},{"name":"Ulysses Butterfly","rarity":"legendary","id":"ulysses-butterfly","subtitle":"Butterfly","details":"Also called the blue mountain swallowtail, this vivid electric-blue butterfly dances through rainforests of northeastern Australia and New Guinea.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papilio%20ulysses%20at%20Kuranda%20Butterfly%20Sanctuary.jpg?width=1024"},{"name":"Rajah Brooke's Birdwing","rarity":"legendary","id":"rajah-brookes-birdwing","subtitle":"Butterfly","details":"Males flash iridescent green triangles on velvet-black wings as this large birdwing glides through the rainforests of Borneo and the Malay Peninsula.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Trogonoptera%20brookiana%200588.JPG?width=1024"},{"name":"Apollo Butterfly","rarity":"legendary","id":"apollo-butterfly","subtitle":"Butterfly","details":"A mountain butterfly of Europe and Asia, it wears white wings dotted with black and red eyespots and drifts over sunny alpine meadows in summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Parnassius%20apollo%2004.jpg?width=1024"},{"name":"Cairns Birdwing","rarity":"legendary","id":"cairns-birdwing","subtitle":"Butterfly","details":"Australia's largest butterfly: males shine green and gold over black, while larger females wear brown wings marked with white and yellow patches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cairns%20Birdwing%20%28Ornithoptera%20euphorion%29%20male.jpg?width=1024"},{"name":"Emerald Swallowtail","rarity":"legendary","id":"emerald-swallowtail","subtitle":"Butterfly","details":"Metallic green bands shimmer across the dark wings of this Asian swallowtail, gliding through shaded forest clearings from India to the Philippines.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papilio%20palinurus%20%281%29.jpg?width=1024"},{"name":"Dead Leaf Butterfly","rarity":"legendary","id":"dead-leaf-butterfly","subtitle":"Butterfly","details":"With wings closed it mimics a dried brown leaf, vein and all, but opened it reveals bright orange and blue bands across forests of tropical Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Partially%20open%20wing%20feeding%20activity%20of%20Kallima%20inachus%20%28Doy%C3%A8re%2C%201840%29%20-%20Orange%20Oakleaf%20WLB%20DSC%206775a.jpg?width=1024"},{"name":"Luna Moth","rarity":"legendary","id":"luna-moth","subtitle":"Moth","details":"A pale green silk moth with long twisting tails and feathery antennae, the luna moth lives only about a week as an adult and does not feed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-%207758%20%E2%80%93%20Actias%20luna%20%E2%80%93%20Luna%20Moth%20%2840831007503%29.jpg?width=1024"},{"name":"Madagascan Sunset Moth","rarity":"legendary","id":"madagascan-sunset-moth","subtitle":"Moth","details":"A day-flying moth from Madagascar whose black wings flash rainbow colours as light shifts across tiny scales on its wing surfaces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chrysiridia%20rhipheus-mada-alive%3Dvivant.jpg?width=1024"},{"name":"Hercules Moth","rarity":"legendary","id":"hercules-moth","subtitle":"Moth","details":"Found in New Guinea and northern Australia, this giant silk moth has the largest wing surface area of any moth ever recorded.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coscinocera%20hercules%2C%20North%20Queensland.jpg?width=1024"},{"name":"Rainbow Stag Beetle","rarity":"legendary","id":"rainbow-stag-beetle","subtitle":"Beetle","details":"An Australian stag beetle whose shell shimmers through greens, blues and purples as light moves across its polished wing cases.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phalacrognathus%20muelleri.jpg?width=1024"},{"name":"Giraffe Stag Beetle","rarity":"legendary","id":"giraffe-stag-beetle","subtitle":"Beetle","details":"One of the world's largest stag beetles, males carry enormously long jaws that can exceed the length of the rest of their body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giraffe%20stag%20beetle%20%28Prosopocoilus%20giraffa%29%2C%20Entomica%201.jpg?width=1024"},{"name":"Atlas Beetle","rarity":"legendary","id":"atlas-beetle","subtitle":"Beetle","details":"A powerful three-horned rhinoceros beetle of Southeast Asia, named for the titan Atlas and famed for lifting many times its own weight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atlas%20beetle%20%28Chalcosoma%20atlas%29%2C%20Reptiland%2C%20Riva%20del%20Garda%2C%20Italy.jpg?width=1024"},{"name":"Japanese Rhinoceros Beetle","rarity":"legendary","id":"japanese-rhinoceros-beetle","subtitle":"Beetle","details":"A glossy chestnut beetle with a forked head horn, treasured in Japan where it is a familiar summer sight on sap flows in oak woods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Japanese%20rhinoceros%20beetle%20%28Trypoxylus%20dichotomus%29%20%2820492490700%29.jpg?width=1024"},{"name":"Glorious Scarab","rarity":"legendary","id":"glorious-scarab","subtitle":"Beetle","details":"A jewel scarab of the American Southwest and Mexico whose shell gleams metallic green and gold, found high in mountain juniper woods.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jewel%20Scarab%20-%20Chrysina%20gloriosa%20%287898749892%29.jpg?width=1024"},{"name":"Elephant Beetle","rarity":"legendary","id":"elephant-beetle","subtitle":"Beetle","details":"A massive rhinoceros beetle of Central America, males bearing a long central horn flanked by two shorter horns like an elephant's tusks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coleoptera%20-%20Megasoma%20elephas%20-%203.jpg?width=1024"},{"name":"Western Honey Bee","rarity":"legendary","id":"western-honey-bee","subtitle":"Bee","details":"Honey bees live in large colonies with a single queen, and workers communicate the location of flowers through a waggle dance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Apis%20mellifera%20-%20Cirsium%20arvense%20-%20Keila.jpg?width=1024"},{"name":"Buff-tailed Bumblebee","rarity":"legendary","id":"buff-tailed-bumblebee","subtitle":"Bee","details":"This large, fuzzy bumblebee is an important pollinator of wildflowers and crops, and queens found new colonies each spring.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Bombus%20terrestris%20on%20phlomis%20fruticosa.jpg?width=1024"},{"name":"Asian Giant Hornet","rarity":"legendary","id":"asian-giant-hornet","subtitle":"Hornet","details":"The world's largest hornet, this species nests mostly underground and hunts other insects to feed its growing colony through the season.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20200512-P1090972%20Vespa%20mandarinia%20japonica.jpg?width=1024"},{"name":"Emperor Dragonfly","rarity":"legendary","id":"emperor-dragonfly","subtitle":"Dragonfly","details":"One of Europe's largest dragonflies, the emperor patrols ponds tirelessly and rarely lands, hunting other insects on the wing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anax%20Imperator%202%28loz%29.JPG?width=800"},{"name":"Common Green Darner","rarity":"legendary","id":"common-green-darner","subtitle":"Dragonfly","details":"Green darners migrate hundreds of miles in multi-generational journeys, among the longest insect migrations in North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anax%20junius-Female-1.jpg?width=1024"},{"name":"Black Widow","rarity":"legendary","id":"black-widow","subtitle":"Spider","details":"A glossy black North American spider about 37 mm with legs spread; females show a red hourglass mark and build tangled webs near the ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Latrodectus%20mactans%20eating.JPG?width=1024"},{"name":"Sydney Funnel-web Spider","rarity":"legendary","id":"sydney-funnel-web-spider","subtitle":"Spider","details":"A stocky dark spider from eastern Australia, 5 to 7 cm with legs, that builds a silk-lined burrow with trip lines radiating from its entrance.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atrax%20robustus.jpg?width=1024"},{"name":"Brazilian Wandering Spider","rarity":"legendary","id":"brazilian-wandering-spider","subtitle":"Spider","details":"A large South American ground hunter reaching 15 cm across the legs; it wanders the forest floor at night instead of living in a permanent web.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aranha%20armadeira%28Phoneutria%20nigriventer%29%20por%20Rodrigo%20Tetsuo%20Argenton%20%281%29.jpg?width=1024"},{"name":"Goliath Birdeater","rarity":"legendary","id":"goliath-birdeater","subtitle":"Spider","details":"Among the heaviest spiders, this South American tarantula can reach 28 cm across the legs and hunts insects, frogs and small rodents on foot.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Goliath%20Birdeater%20Tarantula%20%28Theraphosa%20blondi%29%20juvenile%20%28second%20stage%29%20%2838464254746%29.jpg?width=1024"},{"name":"Emperor Scorpion","rarity":"legendary","id":"emperor-scorpion","subtitle":"Scorpion","details":"A large West African scorpion reaching 20 cm, with massive pincer claws; it glows blue-green under ultraviolet light like many other scorpions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Emperor%20scorpion%20or%20Imperial%20scorpion%20%28Pandinus%20imperator%29.jpg?width=1024"},{"name":"Chinese Mantis","rarity":"legendary","id":"chinese-mantis","subtitle":"Mantis","details":"A large mantis introduced to North America, it waits motionless among stems and strikes at passing insects with spined forelegs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chinese%20mantis%20%28Tenodera%20sinensis%29%2C%20Entomica%201.jpg?width=800"},{"name":"Orchid Mantis","rarity":"legendary","id":"orchid-mantis","subtitle":"Mantis","details":"This Southeast Asian mantis mimics an orchid blossom in pink and white, luring pollinating insects within reach of its strike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hymenopus%20coronatus%20Mante%20orchid%C3%A9e%20GLAM%20MHNL%2000.jpg?width=1024"},{"name":"Ghost Mantis","rarity":"legendary","id":"ghost-mantis","subtitle":"Mantis","details":"With leaf-like lobes and a twisted crown, the ghost mantis sways like dead foliage in the dry forests of Africa and Madagascar.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ghost%20mantis%20%28Phyllocrania%20paradoxa%29%2C%20Entomica.jpg?width=1024"},{"name":"Giant Prickly Stick Insect","rarity":"legendary","id":"giant-prickly-stick-insect","subtitle":"Stick Insect","details":"Females of this Australian species are heavy, spiny, and flightless, hanging curled like scorpions among eucalyptus leaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Extatosoma%20tiaratum%20-%20Female%20with%20two%20males.jpg?width=1024"},{"name":"Giant Owl Butterfly","rarity":"epic","id":"giant-owl-butterfly","subtitle":"Butterfly","details":"Huge eyespots on its brown underwings resemble an owl's face, startling predators at dusk in the rainforests of Central and South America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bananenfalter%20Caligo%20memnon%202014.jpg?width=1024"},{"name":"Peacock Butterfly","rarity":"epic","id":"peacock-butterfly","subtitle":"Butterfly","details":"Bold eyespots on rich red wings startle birds, while the dark underside hides this European butterfly among dead leaves through the winter months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peacock%20butterfly%20%28Aglais%20io%29%202.jpg?width=1024"},{"name":"Purple Emperor","rarity":"epic","id":"purple-emperor","subtitle":"Butterfly","details":"Males flash an iridescent purple sheen over dark brown wings and patrol oak woodland canopies in Europe and across northern Asia in midsummer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Purple%20emperor%20%28Apatura%20iris%29%20female.jpg?width=1024"},{"name":"Paper Kite Butterfly","rarity":"epic","id":"paper-kite-butterfly","subtitle":"Butterfly","details":"Large and graceful, its white wings veined and spotted with black drift through forests and butterfly houses from Malaysia to northern Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Idea%20leuconoe%20Dorsal.jpg?width=1024"},{"name":"Blue Pansy","rarity":"epic","id":"blue-pansy","subtitle":"Butterfly","details":"Males shine bright blue above with orange eyespots, while females are browner; both bask on sunny ground across Africa, southern Asia and Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Open%20wing%20basking%20position%20of%20Junonia%20orithya%20%28Linnaeus%2C%201758%29%20-%20Blue%20Pansy%20%28Female%20DSF%29%20%285%29%20WLB.jpg?width=1024"},{"name":"Leopard Lacewing","rarity":"epic","id":"leopard-lacewing","subtitle":"Butterfly","details":"Orange wings laced with black and white markings make this butterfly of South and Southeast Asian forests easy to spot along streams and clearings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Closed%20Wing%20Nectaring%20Position%20of%20Cethosia%20cyane%20%28Drury%2C1773%29%20-%20Leopard%20Lacewing.jpg?width=1024"},{"name":"Clipper Butterfly","rarity":"epic","id":"clipper-butterfly","subtitle":"Butterfly","details":"Strong on brown-and-cream striped wings, this South and Southeast Asian butterfly glides between sunlit patches along forest rivers and edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Partially%20open%20wing%20leaf%20sap%20sucking%20activity%20of%20Parthenos%20sylvia%20%28Cramer%2C%201775%29%20-%20Clipper%20WLB%20DSC%200256.jpg?width=1024"},{"name":"Malachite Butterfly","rarity":"epic","id":"malachite-butterfly","subtitle":"Butterfly","details":"Named for the green mineral, its wings glow translucent green banded with black as it feeds on fallen fruit in forests from Florida to Brazil.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Antillean%20malachite%20%28Siproeta%20stelenes%20stelenes%29.JPG?width=1024"},{"name":"Zebra Longwing","rarity":"epic","id":"zebra-longwing","subtitle":"Butterfly","details":"Black wings striped with pale yellow make this slow, social butterfly easy to recognise; it roosts in groups and ranges from Florida to Peru.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zebra%20heliconian%20longwing%20%28Heliconius%20charithonia%20simulator%29.jpg?width=1024"},{"name":"Plain Tiger","rarity":"epic","id":"plain-tiger","subtitle":"Butterfly","details":"An orange, black and white butterfly widespread across Africa and Asia, it flies openly, confident in the bitter sap of its milkweed host plants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Butterfly%20Plain%20Tiger%20%28Danaus%20chrysippus%29.jpg?width=1024"},{"name":"Rosy Maple Moth","rarity":"epic","id":"rosy-maple-moth","subtitle":"Moth","details":"A small, woolly silk moth in soft pink and cream, the rosy maple moth rests on maple leaves where its colours blend with winged seeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-%207715%20%E2%80%93%20Dryocampa%20rubicunda%20%E2%80%93%20Rosy%20Maple%20Moth%20%2820308956860%29.jpg?width=1024"},{"name":"Cecropia Moth","rarity":"epic","id":"cecropia-moth","subtitle":"Moth","details":"North America's largest native moth, the cecropia shows rich reddish-brown wings marked with crescents and white bands on each wing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cecropia%20Moth%20%28Hyalophora%20cecropia%29.jpg?width=1024"},{"name":"Polyphemus Moth","rarity":"epic","id":"polyphemus-moth","subtitle":"Moth","details":"A giant tan silk moth named for a mythic giant, with a large transparent eyespot ringed in dark colours near the edge of each hindwing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-%207757%20%E2%80%93%20Antheraea%20polyphemus%20%E2%80%93%20Polyphemus%20Moth%20%2848043670111%29.jpg?width=1024"},{"name":"Io Moth","rarity":"epic","id":"io-moth","subtitle":"Moth","details":"A bright yellow silk moth whose hindwings hide bold black-and-blue eyespots, flashed suddenly to startle anything that comes too close.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-%207746%20%E2%80%93%20Automeris%20io%20%E2%80%93%20Io%20Moth%20%2827522144420%29.jpg?width=1024"},{"name":"Comet Moth","rarity":"epic","id":"comet-moth","subtitle":"Moth","details":"A huge yellow silk moth from Madagascar with a long twisted tail on each hindwing, once pictured on Madagascan banknotes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Argema%20mittrei%2001.JPG?width=1024"},{"name":"European Stag Beetle","rarity":"epic","id":"european-stag-beetle","subtitle":"Beetle","details":"Europe's largest beetle, the male's oversized antler-like jaws are used in gentle wrestling matches on summer evenings in old woodland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20200529%20Lucanus%20cervus%2002.jpg?width=1024"},{"name":"Harlequin Beetle","rarity":"epic","id":"harlequin-beetle","subtitle":"Beetle","details":"A huge tropical longhorn beetle with bold black, orange and yellow patterns and front legs longer than its entire ornate body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acrocinus%20longimanus%20%2810948544055%29.jpg?width=1024"},{"name":"Eastern Firefly","rarity":"epic","id":"eastern-firefly","subtitle":"Beetle","details":"A soft-bodied beetle whose abdomen flashes yellow-green light on summer nights, each species blinking in its own distinctive pattern.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Firefly%20-%20Photinus%20pyralis%2C%20Woodbridge%2C%20Virginia.jpg?width=1024"},{"name":"Rainbow Scarab","rarity":"epic","id":"rainbow-scarab","subtitle":"Beetle","details":"A stout dung beetle of North America whose shell shines in metallic greens, blues and copper, rolling and burying brood balls underground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Phanaeus%20vindex%20Macleay%2C%201819%20male%20%284138674192%29.jpg?width=1024"},{"name":"Golden Tortoise Beetle","rarity":"epic","id":"golden-tortoise-beetle","subtitle":"Beetle","details":"A tiny leaf beetle that looks like a drop of polished gold, able to shift colour toward red when disturbed by changing fluid in its shell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Charidotella%20sexpunctata%20293421300.jpg?width=1024"},{"name":"Green Tiger Beetle","rarity":"epic","id":"green-tiger-beetle","subtitle":"Beetle","details":"A fast, metallic green ground hunter of sunny European paths, sprinting in short bursts after prey with its large eyes and long legs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cicindela%20campestris-01%20%28xndr%29.jpg?width=1024"},{"name":"Violet Ground Beetle","rarity":"epic","id":"violet-ground-beetle","subtitle":"Beetle","details":"A large flightless ground beetle with violet-edged wing cases, hunting slugs and worms by night in gardens and woodland across Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Biegacz%20fioletowy%20Carabus%20violaceus%201.jpg?width=1024"},{"name":"Rhinoceros Beetle","rarity":"epic","id":"rhinoceros-beetle","subtitle":"Beetle","details":"An Asian rhinoceros beetle with a single curved horn on its head, glossy dark shell and a sturdy build for pushing through leaf litter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Amal%20effendi%20wiki%20kontes%2001%20Kumbang%20Kelapa%20%28Xylotrupes%20gideon%29.jpg?width=800"},{"name":"Golden Jewel Beetle","rarity":"epic","id":"golden-jewel-beetle","subtitle":"Beetle","details":"A brilliant metallic gold-green jewel beetle of Southeast Asia, its sculpted wing cases flashing like enamel in tropical forest light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chrysochroa%20fulgidissima%20%2848723501341%29.jpg?width=1024"},{"name":"European Paper Wasp","rarity":"epic","id":"european-paper-wasp","subtitle":"Wasp","details":"Paper wasps build open, umbrella-shaped nests from chewed wood fibers mixed with saliva, creating a thin, papery material for the nest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20220802%20Polistes%20dominula%2002.jpg?width=1024"},{"name":"Red Imported Fire Ant","rarity":"epic","id":"red-imported-fire-ant","subtitle":"Ant","details":"Fire ant colonies build loose soil mounds and can link many queens and nests together into very large supercolonies that can cover wide areas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red%20Imported%20Fire%20Ant%20-%20Solenopsis%20invicta%2C%20Okaloacoochee%20Slough%20State%20Forest%2C%20Felda%2C%20Florida%2C%20February%206%2C%202022%20%2851872217415%29.jpg?width=1024"},{"name":"Leafcutter Ant","rarity":"epic","id":"leafcutter-ant","subtitle":"Ant","details":"Leafcutter ants carry leaf pieces many times their weight to the nest, where the leaves feed fungus gardens the colony eats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Atta%20cephalotes-pjt.jpg?width=1024"},{"name":"Blue Orchard Bee","rarity":"epic","id":"blue-orchard-bee","subtitle":"Bee","details":"A solitary mason bee, each female builds her own mud-partitioned nest and is an exceptionally effective orchard pollinator.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mason%20bee%20%28Osmia%20lignaria%29%20%2826134020756%29.jpg?width=1024"},{"name":"Southern Carpenter Ant","rarity":"epic","id":"southern-carpenter-ant","subtitle":"Ant","details":"Carpenter ants excavate galleries in wood to house their colony, with major workers developing notably large heads and powerful jaws for defense.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Camponotus%20floridanus%20casent0104894%20profile%201.jpg?width=1024"},{"name":"Flame Skimmer","rarity":"epic","id":"flame-skimmer","subtitle":"Dragonfly","details":"Mature male flame skimmers glow brilliant orange-red, perching on twigs over warm western ponds to watch for rivals and prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Libellula%20saturata-Female-10.jpg?width=1024"},{"name":"Ebony Jewelwing","rarity":"epic","id":"ebony-jewelwing","subtitle":"Damselfly","details":"This metallic green damselfly with dark wings flutters slowly along shaded forest streams in eastern North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ebony%20Jewelwing.%20female.%20Calopteryx%20maculata%20%2824939626758%29.jpg?width=1024"},{"name":"Common Whitetail","rarity":"epic","id":"common-whitetail","subtitle":"Dragonfly","details":"Male whitetails develop a chalky white abdomen with age, and both sexes perch flat on the ground or low vegetation near ponds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20Whitetail%20%28Plathemis%20lydia%29%2C%20Female%20-%20Kitchener%2C%20Ontario.jpg?width=640"},{"name":"Blue Dasher","rarity":"epic","id":"blue-dasher","subtitle":"Dragonfly","details":"Blue dashers are small, agile pond dragonflies whose males turn powder blue and defend tiny territories around still water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pachydiplax%20longipennis-Female-7.jpg?width=1024"},{"name":"Mexican Redknee Tarantula","rarity":"epic","id":"mexican-redknee-tarantula","subtitle":"Spider","details":"A Mexican tarantula with orange-red knee patches on dark legs, spanning about 15 cm; females of this slow-growing desert species can live 30 years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ParcPhoenixVivarium.jpg?width=1024"},{"name":"Chilean Rose Tarantula","rarity":"epic","id":"chilean-rose-tarantula","subtitle":"Spider","details":"A hardy Chilean tarantula about 15 cm across, covered in rosy pink hairs; it lives in desert scrub burrows and is known for a calm, slow gait.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grammostola%20rosea%20Chilian%20Rose%20Hair%20Tarantula.jpg?width=1024"},{"name":"Golden Silk Orb Weaver","rarity":"epic","id":"golden-silk-orb-weaver","subtitle":"Spider","details":"Found across the warm Americas, females span up to 12 cm and spin strong golden-tinted orb webs that can stretch more than a metre across paths.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Costa%20Rica%2C%20Lim%C3%B3n%2C%20Veragua%20Rainforest%20%28Trichonephila%20clavipes%29.jpg?width=1024"},{"name":"Cane Huntsman Spider","rarity":"epic","id":"cane-huntsman-spider","subtitle":"Spider","details":"A fast, flat-bodied hunter found worldwide in warm regions, spanning up to 13 cm; it chases insects on walls and trees rather than building a web.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2021-7-11-%E8%87%BA%E4%B8%AD-%E7%8E%89%E9%8A%80ATM-%E5%89%8C%E7%8A%BD%28%E9%9B%8C%E9%AB%94%29.jpg?width=1024"},{"name":"Bold Jumping Spider","rarity":"epic","id":"bold-jumping-spider","subtitle":"Spider","details":"A stocky North American jumper about 13 mm long with iridescent green mouthparts; its excellent eyesight helps it stalk and pounce on small prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bold%20jumper%20spider%20%28Phidippus%20audax%29%20with%20captured%20wasp.jpg?width=1024"},{"name":"Redback Spider","rarity":"epic","id":"redback-spider","subtitle":"Spider","details":"An Australian relative of the black widow, about 10 mm for females, marked with a red back stripe and building a messy web in dry sheltered spots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CSIRO%20ScienceImage%201496%20A%20red%20backed%20spider.jpg?width=1024"},{"name":"Deathstalker","rarity":"epic","id":"deathstalker","subtitle":"Scorpion","details":"A yellow scorpion of North African and Middle Eastern deserts, about 10 cm long, with slender claws; it shelters under stones by day, hunting nightly.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Deathstalker%20%28Leiurus%20quinquestriatus%29%207.jpg?width=1024"},{"name":"Arizona Bark Scorpion","rarity":"epic","id":"arizona-bark-scorpion","subtitle":"Scorpion","details":"A pale tan scorpion of the Sonoran Desert, about 8 cm long, that climbs trees and walls and glows under ultraviolet light like most scorpions do.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centruroides%20sculpturatus%20124441417.jpg?width=1024"},{"name":"Giant Malaysian Leaf Insect","rarity":"epic","id":"giant-malaysian-leaf-insect","subtitle":"Stick Insect","details":"This leaf insect copies a broad green leaf down to vein-like markings, and sways gently to imitate foliage moving in a breeze.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pulchriphyllium%20giganteum%2C%20adult%20femal%20from%20dorsal.jpg?width=1024"},{"name":"European Mantis","rarity":"epic","id":"european-mantis","subtitle":"Mantis","details":"The classic praying mantis of Europe, recognized by a black-ringed yellow spot on the inside of each front coxa near the head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European%20mantis%20%28Mantis%20religiosa%29%20eating%20a%20cicada%2002.jpg?width=1024"},{"name":"Periodical Cicada","rarity":"epic","id":"periodical-cicada","subtitle":"Cicada","details":"After seventeen years underground, red-eyed periodical cicadas emerge by the millions in one of nature's great synchronized events.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Magicicada%20septendecim%2C%20teneral%20stage%2C%20Brood%20X.jpg?width=1024"},{"name":"Madagascar Hissing Cockroach","rarity":"epic","id":"madagascar-hissing-cockroach","subtitle":"Cockroach","details":"This large, wingless cockroach hisses by forcing air through modified spiracles, a sound used in courtship and disputes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2021%2003%2007%20Gromphadorhina%20portentosa%200265.png?width=640"},{"name":"Rainbow Grasshopper","rarity":"epic","id":"rainbow-grasshopper","subtitle":"Grasshopper","details":"Painted in red, yellow, black, and blue-green, the rainbow grasshopper advertises that it feeds on low, chemically defended plants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dactylotum%20bicolor%20P1290344b.jpg?width=1024"},{"name":"Eastern Tiger Swallowtail","rarity":"rare","id":"eastern-tiger-swallowtail","subtitle":"Butterfly","details":"Yellow wings with black tiger stripes soar through eastern North American woodlands and gardens; some females wear a dark, iridescent blue-black form.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20Tiger%20Swallowtail%20Papilio%20glaucus%20Wings%202908px.jpg?width=1024"},{"name":"Painted Lady","rarity":"rare","id":"painted-lady","subtitle":"Butterfly","details":"The world's most widespread butterfly, found on every continent except Antarctica, its orange, black and pink-marked wings appear in gardens anywhere.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20moisture%20sucking%20of%20Vanessa%20cardui%20%28Linnaeus%2C%201758%29%20-%20Painted%20Lady%20WLB.jpg?width=1024"},{"name":"Red Admiral","rarity":"rare","id":"red-admiral","subtitle":"Butterfly","details":"A bold black butterfly with red bands and white spots, it basks on walls and tree trunks across North America, Europe and Asia, sipping fallen fruit.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Vanessa%20atalanta%20Piazzo%2002.jpg?width=1024"},{"name":"Mourning Cloak","rarity":"rare","id":"mourning-cloak","subtitle":"Butterfly","details":"Dark maroon wings edged in cream and blue spots let this hardy butterfly overwinter as an adult, emerging on mild days in North America and Eurasia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mourning%20Cloak%20%28Nymphalis%20antiopa%29%20-%20Kitchener%2C%20Ontario.jpg?width=1024"},{"name":"Viceroy Butterfly","rarity":"rare","id":"viceroy-butterfly","subtitle":"Butterfly","details":"Famous for mimicking the monarch, this slightly smaller orange butterfly of North American wetlands carries a curved black line across its hindwings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Limenitis%20archippus%20%28viceroy%20butterfly%29%20%28Kentucky%2C%20USA%29%20%2817257469602%29.jpg?width=1024"},{"name":"White Admiral","rarity":"rare","id":"white-admiral","subtitle":"Butterfly","details":"Dark wings crossed by a broad white band mark northern forms of this North American woodland butterfly, which glides between sunlit forest clearings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Limenitis%20arthemis%20ssp.%20arthemis%20-%20White%20Admiral%2001.jpg?width=1024"},{"name":"Common Mormon","rarity":"rare","id":"common-mormon","subtitle":"Butterfly","details":"A large black swallowtail of South and Southeast Asia; females come in several forms, some mimicking unpalatable rose butterflies to fool predators.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papilio%20polytes%2C%20the%20common%20Mormon%20in%20Jamshedpur%20%28Image%201%20of%202%29.jpg?width=1024"},{"name":"Lime Butterfly","rarity":"rare","id":"lime-butterfly","subtitle":"Butterfly","details":"A fast, restless swallowtail with cream and black chequered wings, common in gardens and citrus groves from India through Southeast Asia to Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20position%20mud%20puddling%20of%20Papilio%20demoleus%20Linnaeus%2C%201758%20%E2%80%93%20Lime%20Swallowtail%20JAYANTI.jpg?width=1024"},{"name":"Tailed Jay","rarity":"rare","id":"tailed-jay","subtitle":"Butterfly","details":"A swift green-spotted black swallowtail that rarely stops moving, darting between flowers in gardens and forests from India to northern Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20tailed%20jay%20%28Graphium%20agamemnon%29%20%2824472661755%29.jpg?width=1024"},{"name":"Common Bluebottle","rarity":"rare","id":"common-bluebottle","subtitle":"Butterfly","details":"Electric blue-green bands cross its dark wings as this strong-flying swallowtail patrols forest paths and gardens from India to Japan and Australia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close%20wing%20Mud%20puddling%20activity%20of%20Graphium%20sarpedon%20%28Linnaeus%2C%201758%29%20-%20Common%20Bluebottle%20%28Male%29%20WLB.jpg?width=1024"},{"name":"Great Spangled Fritillary","rarity":"rare","id":"great-spangled-fritillary","subtitle":"Butterfly","details":"Large orange wings marked with black and silver-scaled undersides light up North American meadows and woodland edges through the summer months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Spangled%20Fritillary%20Speyeria%20cybele%20Damaged%202397px.jpg?width=1024"},{"name":"Gulf Fritillary","rarity":"rare","id":"gulf-fritillary","subtitle":"Butterfly","details":"Bright orange above and spangled with silver beneath, this butterfly flutters around passion vines from the southern United States to Argentina.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gulf%20Fritillary%20-%20Agraulis%20vanillae%2C%20Merritt%20Island%20National%20Wildlife%20Refuge%2C%20Titusville%2C%20Florida.jpg?width=1024"},{"name":"Julia Butterfly","rarity":"rare","id":"julia-butterfly","subtitle":"Butterfly","details":"A fast, bright orange longwing of the Americas, it races along forest edges and clearings from Brazil north to Texas and Florida on elongated wings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Julia%20%28Dryas%20iulia%20zoe%29%20male%20underside.JPG?width=1024"},{"name":"Common Buckeye","rarity":"rare","id":"common-buckeye","subtitle":"Butterfly","details":"Bold eyespots in blue, cream and orange decorate the brown wings of this sun-loving North and Central American butterfly of open fields and roadsides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Junonia%20coenia%20113474323.jpg?width=1024"},{"name":"Queen Butterfly","rarity":"rare","id":"queen-butterfly","subtitle":"Butterfly","details":"A chestnut-brown relative of the monarch with white-spotted wing borders, common in open country from the southern United States to the Caribbean.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Queen%20%28Danaus%20gilippus%20berenice%29.JPG?width=1024"},{"name":"Orange Tip","rarity":"rare","id":"orange-tip","subtitle":"Butterfly","details":"A springtime sign in Europe and temperate Asia: males flash bright orange wingtips over white wings, while both sexes wear mottled green undersides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Anthocharis%20cardamines%20Aurorasommerfugl%20IMG%207766%20ersvika.JPG?width=1024"},{"name":"Isabella Tiger Moth","rarity":"rare","id":"isabella-tiger-moth","subtitle":"Moth","details":"The adult of the familiar woolly bear caterpillar, this cream-and-rose tiger moth is dotted with small dark spots across its wings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-%208129%20%E2%80%93%20Pyrrharctia%20isabella%20%E2%80%93%20Isabella%20Tiger%20Moth%20%2847945008371%29.jpg?width=1024"},{"name":"Garden Tiger Moth","rarity":"rare","id":"garden-tiger-moth","subtitle":"Moth","details":"A boldly patterned moth with chocolate-and-cream forewings and scarlet hindwings spotted with blue-black, found across Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Arctia%20caja%20caja%20-%20Ciechanow%20Poland%20-%20male%20dorsal.jpg?width=1024"},{"name":"Hummingbird Hawk-Moth","rarity":"rare","id":"hummingbird-hawk-moth","subtitle":"Moth","details":"A day-flying hawkmoth that hovers at flowers with a long proboscis, beating its wings so fast they blur like a tiny hummingbird.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2015-07-27%2020-48-16%20Macroglossum-stellatarum.jpg?width=1024"},{"name":"Oleander Hawk-Moth","rarity":"rare","id":"oleander-hawk-moth","subtitle":"Moth","details":"A beautifully marbled green and cream hawkmoth that migrates long distances and visits fragrant white flowers in the evening.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/OLEANDER%20HAWK%20MOTH%20Daphnis%20nerii%20%286270786093%29.jpg?width=1024"},{"name":"Elephant Hawk-Moth","rarity":"rare","id":"elephant-hawk-moth","subtitle":"Moth","details":"An olive and vivid pink hawkmoth of Europe and Asia, named because its caterpillar's swollen head end resembles an elephant's trunk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281991%29%20Elephant%20Hawk-moth%20%28Deilephila%20elpenor%29%20%2828345855975%29.jpg?width=1024"},{"name":"Emperor Moth","rarity":"rare","id":"emperor-moth","subtitle":"Moth","details":"A large day-flying moth of European heathland, with a peacock-like eyespot on each of its four brown and grey patterned wings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-1643-%20Emperor%20Moth%20%28Saturnia%20pavonia%29%20%2849697984173%29.jpg?width=1024"},{"name":"Regal Moth","rarity":"rare","id":"regal-moth","subtitle":"Moth","details":"A stout orange and grey-green silk moth whose caterpillar, the hickory horned devil, is one of North America's largest caterpillars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-%207706%20%E2%80%93%20Citheronia%20regalis%20%E2%80%93%20Regal%20Moth%20%2848043874151%29.jpg?width=1024"},{"name":"Seven-spot Ladybird","rarity":"rare","id":"seven-spot-ladybird","subtitle":"Beetle","details":"Europe's most familiar ladybird, a scarlet beetle with seven black spots whose larvae and adults both feast on aphids in gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/P1170487%20Coccinella%20septempunctata.jpg?width=1024"},{"name":"Cockchafer","rarity":"rare","id":"cockchafer","subtitle":"Beetle","details":"A chunky brown chafer with fan-like antennae and a patterned tail plate, clattering around lights and treetops on warm May evenings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20Cockchafer%20%28Melolontha%20melolontha%29.jpg?width=1024"},{"name":"Rose Chafer","rarity":"rare","id":"rose-chafer","subtitle":"Beetle","details":"A dazzling metallic green and copper chafer that visits roses and elder blossom on sunny days across Europe and western Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cetonia%20aurata%20%28Linnaeus%201761%29.jpg?width=1024"},{"name":"Lesser Stag Beetle","rarity":"rare","id":"lesser-stag-beetle","subtitle":"Beetle","details":"A smaller, sooty-black stag beetle of European woodland, often found on paths and fences near the dead wood its larvae develop in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Balkenschr%C3%B6ter%20Dorcus%20parallelipipedus%201.jpg?width=1024"},{"name":"Devil's Coach Horse","rarity":"rare","id":"devils-coach-horse","subtitle":"Beetle","details":"A long black rove beetle that raises its tail like a scorpion when threatened, hunting other invertebrates in damp gardens and woodland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Escarabajo%20errante%20%28Ocypus%20olens%29%2C%20Hartelholz%2C%20M%C3%BAnich%2C%20Alemania%2C%202020-06-28%2C%20DD%20440-475%20FS.jpg?width=1024"},{"name":"Bloody-nosed Beetle","rarity":"rare","id":"bloody-nosed-beetle","subtitle":"Beetle","details":"A slow, flightless leaf beetle of European coasts and heaths that defends itself by releasing drops of red fluid from its mouth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bloody-Nosed%20Beetle%20%28Timarcha%20tenebricosa%29%20%283866559007%29.jpg?width=1024"},{"name":"Wasp Beetle","rarity":"rare","id":"wasp-beetle","subtitle":"Beetle","details":"A harmless longhorn beetle with yellow-and-black wasp markings and jerky movements, often seen on flowers and dead wood in summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2013-06-07%2021-02-52-Clytus-arietis.JPG?width=1024"},{"name":"Spotted Longhorn","rarity":"rare","id":"spotted-longhorn","subtitle":"Beetle","details":"A yellow-and-black longhorn beetle common on European summer flowers, its bold pattern varying between mostly dark and mostly golden.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Rutpela%20maculata%20on%20Carpinus%20betulus.jpg?width=800"},{"name":"Rosemary Beetle","rarity":"rare","id":"rosemary-beetle","subtitle":"Beetle","details":"A jewel-like leaf beetle with metallic green and purple stripes, found on rosemary, lavender and other aromatic herbs in warm gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chrysolina%20americana%20-%20Ben%20Sale%20-%202012%20%287188846071%29.jpg?width=800"},{"name":"Blue Death Feigning Beetle","rarity":"rare","id":"blue-death-feigning-beetle","subtitle":"Beetle","details":"A powdery blue desert beetle of the American Southwest that plays dead when disturbed, and can live for many years as an adult.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asbolus%20verrucosus.jpg?width=1024"},{"name":"Sawyer Beetle","rarity":"rare","id":"sawyer-beetle","subtitle":"Beetle","details":"A grey-speckled longhorn beetle of North American pine woods, with antennae longer than its body and a rasping patch behind its head.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Monochamus%20scutellatus%20P1210688a.jpg?width=1024"},{"name":"Eyed Click Beetle","rarity":"rare","id":"eyed-click-beetle","subtitle":"Beetle","details":"A large click beetle with two bold false eyespots on its thorax, able to snap its body to flip upright with an audible click.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alaus%20oculatus%201.jpg?width=800"},{"name":"Cottonwood Borer","rarity":"rare","id":"cottonwood-borer","subtitle":"Beetle","details":"A striking black-and-cream longhorn beetle of North America with extremely long antennae, associated with cottonwood and willow trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Plectrodera%20scalator%20%2815052725840%29.jpg?width=1024"},{"name":"Red Milkweed Beetle","rarity":"rare","id":"red-milkweed-beetle","subtitle":"Beetle","details":"A bright red longhorn beetle found on milkweed plants, with long antennae divided between black and red along their length.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cerambycidae-%20Tetraopes%20tetrophthalmus%20%28Red%20Milkweed%20Beetle%29.jpg?width=1024"},{"name":"Common Eastern Bumblebee","rarity":"rare","id":"common-eastern-bumblebee","subtitle":"Bee","details":"One of North America's most widespread bumblebees, it pollinates many crops and can forage in cooler weather than honey bees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bombus%20impatiens%2C%20f%2C%20queen%2C%20charles%20co%20%2818239590966%29.jpg?width=1024"},{"name":"German Yellowjacket","rarity":"rare","id":"german-yellowjacket","subtitle":"Wasp","details":"German yellowjackets build enclosed paper nests, often underground, and colonies can grow to thousands of workers by autumn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AD2009Sep09%20Vespula%20germanica%2007.jpg?width=1024"},{"name":"Red Harvester Ant","rarity":"rare","id":"red-harvester-ant","subtitle":"Ant","details":"Harvester ants gather seeds into underground granaries and clear wide, gravel-covered discs around their nest entrances.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hymenoptera%20-%20Pogonomyrmex%20barbatus%20-%201.jpg?width=1024"},{"name":"Eastern Carpenter Bee","rarity":"rare","id":"eastern-carpenter-bee","subtitle":"Bee","details":"Carpenter bees bore round tunnels into wood to raise their young, and males hover near nests but cannot sting, though they can hover and feed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/319%20365%20-%20Eastern%20Carpenter%20Bee%20-%20Xylocopa%20virginica%2C%20Woodbridge%2C%20Virginia%2C%20November%2015%2C%202023%20%2853339222819%29.jpg?width=1024"},{"name":"Bald-faced Hornet","rarity":"rare","id":"bald-faced-hornet","subtitle":"Hornet","details":"Despite its name it is a yellowjacket wasp, building large enclosed paper nests high in trees and on buildings, shrubs, and sheltered eaves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bald-Faced%20Hornet%20%28Dolichovespula%20maculata%29%20%2812513190215%29.jpg?width=1024"},{"name":"Great Golden Digger Wasp","rarity":"rare","id":"great-golden-digger-wasp","subtitle":"Wasp","details":"This solitary wasp digs burrows in sandy soil and stocks them with paralyzed grasshoppers as food for its larvae in chambers underground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Golden%20Digger%20Wasp%20%28Sphecidae%2C%20Sphex%20ichneumoneus%20%28Linnaeus%29%29%20%2836164431831%29.jpg?width=1024"},{"name":"Velvet Ant","rarity":"rare","id":"velvet-ant","subtitle":"Wasp","details":"Velvet ants are actually wingless female wasps covered in dense, bright hairs, and they wander open ground searching for host nests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cow%20Killer%20-%20Dasymutilla%20occidentalis%2C%20Lake%20Woodruff%20National%20Wildlife%20Refuge%2C%20Florida.jpg?width=1024"},{"name":"Eastern Pondhawk","rarity":"rare","id":"eastern-pondhawk","subtitle":"Dragonfly","details":"Pondhawks are powerful hunters that perch low and sally out after prey; males turn blue while females stay bright green.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20Pondhawk%20%28Erythemis%20simplicicollis%29%2C%20Female%2001.jpg?width=1024"},{"name":"Twelve-spotted Skimmer","rarity":"rare","id":"twelve-spotted-skimmer","subtitle":"Dragonfly","details":"Named for the dark spots on its wings, this large skimmer patrols pond edges and often perches on the tips of tall stems.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Libellula%20pulchella%2036631322.jpg?width=1024"},{"name":"Wandering Glider","rarity":"rare","id":"wandering-glider","subtitle":"Dragonfly","details":"The world's most widespread dragonfly, the wandering glider crosses oceans on migration and breeds in temporary rain pools.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pantala%20flavescens-Kadavoor-2017-05-04-002.jpg?width=1024"},{"name":"Rambur's Forktail","rarity":"rare","id":"ramburs-forktail","subtitle":"Damselfly","details":"A slender damselfly of brackish and fresh waters in the Americas, females come in several color forms including male-like blue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ischnura%20ramburii%20%28Selys%2C%201850%29%20-%20Rambur%27s%20forktail.jpg?width=1024"},{"name":"Halloween Pennant","rarity":"rare","id":"halloween-pennant","subtitle":"Dragonfly","details":"With orange-tinted wings banded in dark brown, the Halloween pennant perches butterfly-like on the tips of pond weeds.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Celithemis%20eponina-female.jpg?width=1024"},{"name":"Green Lynx Spider","rarity":"rare","id":"green-lynx-spider","subtitle":"Spider","details":"A bright green hunting spider of the Americas, about 22 mm with legs, that waits on leaves and flowers to ambush insects without using a web.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Peucetia%20viridans%2C%20Sierra%20de%20Guadalupe%2C%20Mexico%2020251108p2.jpg?width=1024"},{"name":"Spinybacked Orb Weaver","rarity":"rare","id":"spinybacked-orb-weaver","subtitle":"Spider","details":"A small orb weaver about 9 mm wide with six spines on a hard, colourful shell-like abdomen; it rebuilds its neat circular web almost every day.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-%20panoramio%20%28740%29.jpg?width=1024"},{"name":"Pinktoe Tarantula","rarity":"rare","id":"pinktoe-tarantula","subtitle":"Spider","details":"A tree-dwelling South American tarantula about 15 cm across, dark with pink-tipped toes; it makes silk tube webs in plants and hollow trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Avicularia%20avicularia.jpg?width=800"},{"name":"Curlyhair Tarantula","rarity":"rare","id":"curlyhair-tarantula","subtitle":"Spider","details":"A Central American tarantula covered in long curling golden hairs, spanning about 15 cm; it digs burrows under roots and leaf litter to rest in.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Curlyhair%20tarantula%20%28Tliltocatl%20albopilosus%29%2C%20Entomica.jpg?width=1024"},{"name":"Brown Recluse Spider","rarity":"rare","id":"brown-recluse-spider","subtitle":"Spider","details":"A small brown spider of central North America, about 20 mm with legs, recognised by a dark violin-shaped mark and six eyes in three pairs.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Loxosceles%20reclusa%20140831962.jpg?width=1024"},{"name":"Carolina Wolf Spider","rarity":"rare","id":"carolina-wolf-spider","subtitle":"Spider","details":"One of the largest wolf spiders in North America, spanning up to 10 cm; females dig burrows and carry their spiderlings on their backs for weeks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hogna%20carolinensis%20female%2C%20crop.jpg?width=1024"},{"name":"Dark Fishing Spider","rarity":"rare","id":"dark-fishing-spider","subtitle":"Spider","details":"A large grey-brown spider of eastern North America, spanning up to 10 cm, that hunts on tree trunks, fences and rocks as well as beside streams.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ara%C3%B1a%20pescadora%20%28Dolomedes%20tenebrosus%29.jpg?width=1024"},{"name":"Woodlouse Spider","rarity":"rare","id":"woodlouse-spider","subtitle":"Spider","details":"A reddish-orange spider about 10 mm long with large forward fangs shaped for piercing woodlice; it hides by day in a silk sac under bark or stones.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Detail%20of%20spider%20%28Dysdera%20crocata%29%20with%20secretions%20between%20massive%20chelicerae%20-%20DSG1941-1%20-%202022-11-08%20%28magnif.%20ratio%202.8x%2C%20HiRes%29.jpg?width=1024"},{"name":"Ravine Trapdoor Spider","rarity":"rare","id":"ravine-trapdoor-spider","subtitle":"Spider","details":"A North American spider with a hard, flat-topped abdomen that plugs its burrow entrance; it waits behind a camouflaged silk trapdoor for prey.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cyclocosmia%20truncata.jpg?width=1024"},{"name":"Asian Forest Scorpion","rarity":"rare","id":"asian-forest-scorpion","subtitle":"Scorpion","details":"A large shiny black scorpion of Southeast Asian forests, reaching 16 cm, with heavy claws; it lives in burrows under logs and leaf litter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asian%20Forest%20Scorpion%20%28Heterometrus%20spinifer%29%20%287802916532%29.jpg?width=1024"},{"name":"Giant Desert Hairy Scorpion","rarity":"rare","id":"giant-desert-hairy-scorpion","subtitle":"Scorpion","details":"The largest scorpion in North America at about 14 cm, covered in sensory hairs; this Sonoran Desert burrower hunts insects and small scorpions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20hairy%20scorpion%2C%20Twentynine%20Palms%2C%20Ca%202813%20RobbHannawacker.jpg?width=1024"},{"name":"Striped Bark Scorpion","rarity":"rare","id":"striped-bark-scorpion","subtitle":"Scorpion","details":"A striped yellow-brown scorpion of the southern United States and Mexico, about 7 cm long, often found under bark, stones and wood piles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Centruroides%20vittatus%20115756050.jpg?width=1024"},{"name":"Carolina Mantis","rarity":"rare","id":"carolina-mantis","subtitle":"Mantis","details":"A native mantis of the southern United States, females are short-winged and cannot fly, while the males are slender fliers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carolina%20Mantis%20%28Stagmomantis%20carolina%29%20%2810246694906%29.jpg?width=1024"},{"name":"Dead Leaf Mantis","rarity":"rare","id":"dead-leaf-mantis","subtitle":"Mantis","details":"This Malaysian mantis flattens into a crumpled dead leaf, complete with a broad shield and ragged edges, when it feels threatened.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adult%20female%20Deroplatys%20desiccata.jpg?width=1024"},{"name":"European Field Cricket","rarity":"rare","id":"european-field-cricket","subtitle":"Cricket","details":"Field crickets dig burrows in sunny grassland and males sing from the entrance, amplifying their chirps across the meadow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Feldgrille%20Gryllus%20campestris.jpg?width=1024"},{"name":"House Cricket","rarity":"rare","id":"house-cricket","subtitle":"Cricket","details":"Originally from southwest Asia, the house cricket now lives worldwide near buildings and is known for its steady evening chirping.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Acheta%20domesticus%2C%20adultes%20Weibchen.jpg?width=1024"},{"name":"Differential Grasshopper","rarity":"rare","id":"differential-grasshopper","subtitle":"Grasshopper","details":"This large yellow-green grasshopper bears black chevron markings on its hind legs and gathers in gardens and crop edges in summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chapul%C3%ADn%20diferencial%20%28Melanoplus%20differentialis%29.jpg?width=1024"},{"name":"Red-legged Grasshopper","rarity":"rare","id":"red-legged-grasshopper","subtitle":"Grasshopper","details":"Named for its bright red hind tibiae, this grasshopper is one of the most abundant meadow species across much of North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Melanoplus%20femurrubrum%2020070903.jpg?width=1024"},{"name":"Common True Katydid","rarity":"rare","id":"common-true-katydid","subtitle":"Katydid","details":"Hidden high in oak canopies, true katydids sing the rasping night chorus that gave katydids their name in eastern forests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pterophylla%20camellifolia.jpg?width=1024"},{"name":"Spotted Lanternfly","rarity":"rare","id":"spotted-lanternfly","subtitle":"Bug","details":"This planthopper hides grey forewings over scarlet hindwings, flashing the bright color in flight, and feeds on tree sap.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adult%20Lycorma%20delicatula.jpg?width=1024"},{"name":"Giant Water Bug","rarity":"rare","id":"giant-water-bug","subtitle":"Bug","details":"Among the largest true bugs, giant water bugs breathe through tail straps at the surface and hunt snails, fish, and tadpoles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American%20Giant%20Water%20Bug%20%28Lethocerus%20americanus%29.jpg?width=1024"},{"name":"Eastern Lubber Grasshopper","rarity":"rare","id":"eastern-lubber-grasshopper","subtitle":"Grasshopper","details":"Big, heavy, and nearly flightless, the eastern lubber moves in slow groups through the wetlands and roadsides of the Southeast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Romalea%20Microptera%20-%20Lubber%20Grasshopper%2002.jpg?width=1024"},{"name":"Greater Angle-wing Katydid","rarity":"rare","id":"greater-angle-wing-katydid","subtitle":"Katydid","details":"This large green katydid hides in tree canopies behind broad, leaf-like wings, and males sing short sharp ticks on summer nights.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/GREATER%20ANGLE-WING%20%28Microcentrum%20rhombifolium%29%20%2810-9-12%29%20garden%20cyn%2C%20huachuca%20mts%2C%20cochise%20co%2C%20az%20-01%20%288074907061%29.jpg?width=1024"},{"name":"Baltimore Checkerspot","rarity":"uncommon","id":"baltimore-checkerspot","subtitle":"Butterfly","details":"Black wings chequered with orange and cream make this wetland butterfly, the state insect of Maryland, a sight in eastern North American marshes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Euphydryas%20phaeton%204zz.jpg?width=1024"},{"name":"Pearl Crescent","rarity":"uncommon","id":"pearl-crescent","subtitle":"Butterfly","details":"A small orange and black butterfly of North American fields and roadsides, named for the pale pearly patch at the centre of its hindwing underside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pearl%20Crescent%20%28Phyciodes%20tharos%29%2C%20ventral.jpg?width=1024"},{"name":"Variegated Fritillary","rarity":"uncommon","id":"variegated-fritillary","subtitle":"Butterfly","details":"Tawny orange wings with intricate black marbling, and no silver beneath, distinguish this wide-ranging butterfly of open habitats across the Americas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Variegated%20Fritillary%20-%20Euptoieta%20claudia%2C%20Meadowwood%20Farm%20SRMA%2C%20Mason%20Neck%2C%20Virginia.jpg?width=1024"},{"name":"American Lady","rarity":"uncommon","id":"american-lady","subtitle":"Butterfly","details":"Orange and black wings with pinkish undersides marked by a bold white web pattern; this migratory butterfly ranges from Canada to Central America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American%20Lady%20-%20Vanessa%20virginiensis%2C%20Hardware%20River%20Wildlife%20Management%20Area%2C%20Scottsville%2C%20Virginia%2C%20June%2023%2C%202021%20%2851829030905%29.jpg?width=1024"},{"name":"Question Mark","rarity":"uncommon","id":"question-mark","subtitle":"Butterfly","details":"Named for the silver question-mark on its hindwing underside, this ragged-edged orange butterfly frequents woodland edges in eastern North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Question%20Mark%20Polygonia%20interrogationis%20Wings%203008px.jpg?width=1024"},{"name":"Comma Butterfly","rarity":"uncommon","id":"comma-butterfly","subtitle":"Butterfly","details":"Jagged wing edges and a white comma mark beneath help this orange-brown European and Asian butterfly vanish among dead leaves at rest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Comma%20%28Polygonia%20c-album%29%20female%20form%20hutchinsoni%20Hungary.jpg?width=1024"},{"name":"Small Tortoiseshell","rarity":"uncommon","id":"small-tortoiseshell","subtitle":"Butterfly","details":"One of Europe's most familiar butterflies, its orange-red wings carry black and yellow markings and a border of small blue crescents along the edges.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aglais%20urticae%2C%20Tokat%2001.jpg?width=1024"},{"name":"Brimstone Butterfly","rarity":"uncommon","id":"brimstone-butterfly","subtitle":"Butterfly","details":"Sulphur-yellow, leaf-shaped wings make this spring butterfly of Europe and Asia a herald of warmer days; females are a much paler greenish white.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20brimstone%20%28Gonepteryx%20rhamni%29%20female%20underside.JPG?width=1024"},{"name":"Common Blue","rarity":"uncommon","id":"common-blue","subtitle":"Butterfly","details":"Males are violet-blue above while females are browner with orange spots; this butterfly flutters over grasslands across Europe and temperate Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Common%20blue%20%28Polyommatus%20icarus%29%20male%20Turna.jpg?width=1024"},{"name":"Holly Blue","rarity":"uncommon","id":"holly-blue","subtitle":"Butterfly","details":"A delicate sky-blue butterfly of gardens and hedgerows in Europe and Asia, it flies in spring and again in summer, often high around holly and ivy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Holly%20blue%20butterfly%20%28Celastrina%20argiolus%29%20female.jpg?width=1024"},{"name":"Large Blue","rarity":"uncommon","id":"large-blue","subtitle":"Butterfly","details":"A striking blue butterfly of European grasslands whose caterpillars are carried into ant nests, where they feed and pupate under the ants' protection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Phengaris%20arion%20-%20Radawa%20Poland%20-%20male.jpg?width=800"},{"name":"Green Hairstreak","rarity":"uncommon","id":"green-hairstreak","subtitle":"Butterfly","details":"The only green British butterfly, its iridescent green underside flashes as it perches on shrubs across Europe, Asia and North Africa.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Green%20hairstreak%20%28Callophrys%20rubi%29%20head.jpg?width=1024"},{"name":"Gray Hairstreak","rarity":"uncommon","id":"gray-hairstreak","subtitle":"Butterfly","details":"A small grey butterfly with an orange spot and fine tail on each hindwing, common in open habitats from Canada through the United States to Colombia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Strymon%20melinus%20gray%20hairstreak%20butterfly.JPG?width=1024"},{"name":"Eastern Tailed-Blue","rarity":"uncommon","id":"eastern-tailed-blue","subtitle":"Butterfly","details":"Tiny and delicate, with thread-like tails and orange-capped hindwing eyespots, it flutters low over eastern North American fields.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eastern%20tailed-blue%20%28Cupido%20comyntas%20texana%29%20underside%20Cundinamarca.jpg?width=1024"},{"name":"Silver-spotted Skipper","rarity":"uncommon","id":"silver-spotted-skipper","subtitle":"Butterfly","details":"A fast-flying North American skipper, brown with bold silver and gold patches, it darts between flowers and perches with wings held at an angle.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Silver-spotted%20Skipper%20Epargyreus%20clarus%20Feeding%202116px.jpg?width=1024"},{"name":"Southern Dogface","rarity":"uncommon","id":"southern-dogface","subtitle":"Butterfly","details":"Its yellow forewing carries a black-edged patch shaped like a dog's profile, a mark on this butterfly of the southern United States and Mexico.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Zerene%20cesonia-Mus%C3%A9e%20zoologique%20de%20Strasbourg.jpg?width=1024"},{"name":"Great Purple Hairstreak","rarity":"uncommon","id":"great-purple-hairstreak","subtitle":"Butterfly","details":"A North American hairstreak with iridescent blue-green uppersides, bold orange patches and long tails, most often seen near mistletoe-bearing trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Great%20Purple%20Hairstreak%2Cfemale%20%28Atlides%20halesus%29.jpg?width=1024"},{"name":"American Copper","rarity":"uncommon","id":"american-copper","subtitle":"Butterfly","details":"A tiny, fiery orange butterfly that darts over dry fields and gardens; it is found across North America and also in Europe and northern Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American%20Copper%20-%20Lycaena%20phlaeas%2C%20Idylwild%20State%20Wildlife%20Management%20Area%2C%20Federalsburg%2C%20Maryland%20%2835150270616%29.jpg?width=1024"},{"name":"Black Swallowtail","rarity":"uncommon","id":"black-swallowtail","subtitle":"Butterfly","details":"Black wings with rows of yellow spots and blue-and-orange eyespots near the tails; this garden butterfly ranges across most of North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papilio%20polyxenes%20MD1.jpg?width=1024"},{"name":"Giant Swallowtail","rarity":"uncommon","id":"giant-swallowtail","subtitle":"Butterfly","details":"North America's largest butterfly, dark brown with yellow bands forming an hourglass, it flaps through woodlands and citrus groves of the east.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Giant%20Swallowtail%2C%20Shirleys%20Bay.jpg?width=1024"},{"name":"Spicebush Swallowtail","rarity":"uncommon","id":"spicebush-swallowtail","subtitle":"Butterfly","details":"Dark wings dusted blue-green with orange hindwing spots; this butterfly of eastern North American forests is named for one of its host plants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Papilio%20troilus%20P1260031a.jpg?width=1024"},{"name":"Pipevine Swallowtail","rarity":"uncommon","id":"pipevine-swallowtail","subtitle":"Butterfly","details":"Iridescent blue-green hindwings flash over black forewings as this butterfly glides through North and Central American woodlands, gardens and meadows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pipevine%20Swallowtail%20-%20Battus%20philenor%2C%20Great%20Smoky%20Mountains%20National%20Park%2C%20North%20Carolina.jpg?width=1024"},{"name":"Cloudless Sulphur","rarity":"uncommon","id":"cloudless-sulphur","subtitle":"Butterfly","details":"A large, bright lemon-yellow butterfly that flies high and fast over open country from Argentina through the Americas to the southern United States.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cloudless%20Sulphur%20-%20Phoebis%20sennae%2C%20Nokesville%2C%20Virginia%20%2835580952154%29.jpg?width=1024"},{"name":"Orange Sulphur","rarity":"uncommon","id":"orange-sulphur","subtitle":"Butterfly","details":"Golden-orange wings with dark borders make this one of North America's commonest butterflies, abundant in alfalfa fields, meadows and roadside clover.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Colias%20eurytheme%20101478441.jpg?width=1024"},{"name":"Cinnabar Moth","rarity":"uncommon","id":"cinnabar-moth","subtitle":"Moth","details":"A striking day-flying moth with charcoal forewings barred in scarlet and bright red hindwings, often seen drifting over summer grassland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cinnabar%20moth%20%28Tyria%20jacobaeae%29.jpg?width=1024"},{"name":"Six-spot Burnet","rarity":"uncommon","id":"six-spot-burnet","subtitle":"Moth","details":"A metallic green day-flying moth with six vivid crimson spots on each forewing, common on flower-rich grasslands across Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%280169%29%20Six-Spot%20Burnet%20Zygaena%20filipendulae%20%283717914510%29.jpg?width=1024"},{"name":"Emperor Gum Moth","rarity":"uncommon","id":"emperor-gum-moth","subtitle":"Moth","details":"A large Australian silk moth with russet wings and clear eyespots, whose plump green caterpillars feed high in eucalyptus trees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Opodiphthera%20eucalypti%20%283239197371%29.jpg?width=1024"},{"name":"Imperial Moth","rarity":"uncommon","id":"imperial-moth","subtitle":"Moth","details":"A big yellow and purple-brown silk moth of the Americas, camouflaged like a dead leaf when it rests with wings spread on the ground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-%207704%20%E2%80%93%20Eacles%20imperialis%20%E2%80%93%20Imperial%20Moth%20%2816225688442%29.jpg?width=800"},{"name":"White-lined Sphinx","rarity":"uncommon","id":"white-lined-sphinx","subtitle":"Moth","details":"A widespread hawkmoth with a bold white stripe along each forewing, flying by day and dusk across much of the Americas and beyond.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hyles%20lineata%20-%20White-lined%20Sphinx%20Moth%20-%209647817889.jpg?width=1024"},{"name":"Privet Hawk-Moth","rarity":"uncommon","id":"privet-hawk-moth","subtitle":"Moth","details":"One of Europe's largest hawkmoths, with pink-and-black banding on its body and long brown wings streaked like tree bark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281976%29%20Privet%20Hawk-moth%20%28Sphinx%20ligustri%29%20%2835234735815%29.jpg?width=1024"},{"name":"Eyed Hawk-Moth","rarity":"uncommon","id":"eyed-hawk-moth","subtitle":"Moth","details":"A bark-patterned hawkmoth that, when disturbed, flashes hindwings bearing large blue-and-black peacock eyespots to surprise predators.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Smerinthus%20ocellata.JPG?width=1024"},{"name":"Peppered Moth","rarity":"uncommon","id":"peppered-moth","subtitle":"Moth","details":"A classic camouflage moth of the northern hemisphere, found in pale speckled and dark sooty forms that blend with bark and stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281931%29%20Peppered%20Moth%20%28Biston%20betularia%29%20%2814308485779%29.jpg?width=800"},{"name":"Brimstone Moth","rarity":"uncommon","id":"brimstone-moth","subtitle":"Moth","details":"A cheerful lemon-yellow moth with small chestnut marks along the wing edges, fluttering along hedgerows from spring into autumn.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%281906%29%20Brimstone%20Moth%20%28Opisthograptis%20luteolata%29%20%2813865741755%29.jpg?width=800"},{"name":"Jersey Tiger","rarity":"uncommon","id":"jersey-tiger","subtitle":"Moth","details":"A handsome day-and-night moth with cream-striped black forewings and scarlet hindwings, increasingly seen in gardens across Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/-2067-%20Jersey%20Tiger%20%28Euplagia%20quadripunctaria%29%20%2831539972938%29.jpg?width=1024"},{"name":"Soldier Beetle","rarity":"uncommon","id":"soldier-beetle","subtitle":"Beetle","details":"A soft, orange-red beetle common on summer flowers across Europe, where it hunts small insects among the petals and pollen.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Rhagonycha%20fulva%20mating.jpg?width=1024"},{"name":"Common Cardinal Beetle","rarity":"uncommon","id":"common-cardinal-beetle","subtitle":"Beetle","details":"A vivid scarlet beetle with a black head and comb-like antennae, found under bark and on woodland flowers in spring and summer.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pyrochroa-serraticornis-feuerk%C3%A4fer.jpg?width=1024"},{"name":"Sexton Beetle","rarity":"uncommon","id":"sexton-beetle","subtitle":"Beetle","details":"An orange-and-black burying beetle that works in pairs to inter small carcasses, preparing food for its young underground.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lesser%20Vespillo%20Burying%20Beetle%20%28Nicrophorus%20vespilloides%29%20-%20Sortland%2C%20Norway%202023-07-14.jpg?width=1024"},{"name":"Oil Beetle","rarity":"uncommon","id":"oil-beetle","subtitle":"Beetle","details":"A plump, short-winged beetle with a swollen abdomen, seen in spring grassland where its tiny larvae hitch rides on visiting bees.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European%20Oil%20beetle%20Meloe%20proscarabaeus%20from%20Hungary.jpg?width=800"},{"name":"Musk Beetle","rarity":"uncommon","id":"musk-beetle","subtitle":"Beetle","details":"A long, metallic green longhorn beetle that gives off a musky scent, found near willows and wetlands across Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aromia-moschata-10-fws.jpg?width=1024"},{"name":"Black Longhorn Beetle","rarity":"uncommon","id":"black-longhorn-beetle","subtitle":"Beetle","details":"A dark longhorn beetle with a heart-shaped red mark on its thorax, visiting summer flowers in woodland across southern Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Stictoleptura%20cordigera.jpg?width=800"},{"name":"Four-banded Longhorn","rarity":"uncommon","id":"four-banded-longhorn","subtitle":"Beetle","details":"A slender black longhorn beetle crossed by four yellow bands, a familiar sight on summer flowers in European woods and meadows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Leptura%20quadrifasciata1%202006-07-07.JPG?width=800"},{"name":"Wharf Borer","rarity":"uncommon","id":"wharf-borer","subtitle":"Beetle","details":"A tan longhorn beetle associated with damp timber and coastal driftwood, its larvae developing in moist, decaying wood and bark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Nacerdes%20melanura.%20Maine.jpg?width=1024"},{"name":"Green Immigrant Leaf Weevil","rarity":"uncommon","id":"green-immigrant-leaf-weevil","subtitle":"Beetle","details":"A small weevil coated in shimmering green scales, found on nettles and other low plants across Europe and introduced to North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Curculionidae%20-%20Polydrusus%20formosus.JPG?width=1024"},{"name":"Vine Weevil","rarity":"uncommon","id":"vine-weevil","subtitle":"Beetle","details":"A stout, flightless black weevil with fused wing cases and short elbowed antennae, active at night on a wide range of garden plants.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gefurchte%20Dickmaulr%C3%BCssler%20Otiorhynchus%20sulcatus%201.jpg?width=1024"},{"name":"Nut Weevil","rarity":"uncommon","id":"nut-weevil","subtitle":"Beetle","details":"A small chestnut weevil with an exceptionally long curved snout, used by females to drill into developing hazelnuts and acorns.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Curculio-nucum-06-fws.jpg?width=1024"},{"name":"Pine Weevil","rarity":"uncommon","id":"pine-weevil","subtitle":"Beetle","details":"A mottled brown weevil with patches of yellow scales and a long snout, found in conifer forests across Europe and northern Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fichtenr%C3%BCsselk%C3%A4fer%20%28Hylobius%20abietis%29.jpg?width=800"},{"name":"Ground Beetle","rarity":"uncommon","id":"ground-beetle","subtitle":"Beetle","details":"A common black ground beetle with reddish legs, hunting invertebrates at night in gardens, farmland and woodland across Europe.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coleoptera%20-%20Pterostichus%20madidus%20%283442748419%29.jpg?width=1024"},{"name":"Bronze Ground Beetle","rarity":"uncommon","id":"bronze-ground-beetle","subtitle":"Beetle","details":"A large ground beetle with bronze-tinted, sculpted wing cases, hunting in woodland and gardens across Europe and North America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Carabus-nemoralis-03-fws.jpg?width=1024"},{"name":"Rainbow Leaf Beetle","rarity":"uncommon","id":"rainbow-leaf-beetle","subtitle":"Beetle","details":"A rare and beautiful leaf beetle of high European grasslands, its shell shifting through gold, green and red metallic bands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2016%2010%2010%20Chrysolina%20cerealis%20A.jpg?width=1024"},{"name":"Green Dock Beetle","rarity":"uncommon","id":"green-dock-beetle","subtitle":"Beetle","details":"A brilliant metallic green leaf beetle found on dock and sorrel, females swelling enormously with eggs until they resemble green berries.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/4985-Gastrophysa%20viridula%2020110826.jpg?width=1024"},{"name":"Alder Leaf Beetle","rarity":"uncommon","id":"alder-leaf-beetle","subtitle":"Beetle","details":"A deep metallic blue leaf beetle that feeds on alder leaves, sometimes gathering in large shining groups along riverbanks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Agelastica%20alni%20%28aka%29.jpg?width=1024"},{"name":"Cereal Leaf Beetle","rarity":"uncommon","id":"cereal-leaf-beetle","subtitle":"Beetle","details":"A small leaf beetle with a red thorax and blue-black striped wing cases, found on grasses and cereal plants across several continents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cereal%20Leaf%20Beetle.%20Chrysomelidae.%20Oulema%20melanopus%20-%20duftschmidi.%20-%20Flickr%20-%20gailhampshire.jpg?width=1024"},{"name":"Harlequin Ladybird","rarity":"uncommon","id":"harlequin-ladybird","subtitle":"Beetle","details":"A highly variable ladybird from Asia, ranging from orange with many spots to black with red patches, now widespread on many continents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Coccinelle%20asiatique%20%28Harmonia%20axyridis%29.jpg?width=1024"},{"name":"Two-spot Ladybird","rarity":"uncommon","id":"two-spot-ladybird","subtitle":"Beetle","details":"A classic red ladybird with one black spot on each wing case, also appearing in a black form with red spots in cooler districts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Adalia%20bipunctata%20101346082.jpg?width=1024"},{"name":"Fourteen-spot Ladybird","rarity":"uncommon","id":"fourteen-spot-ladybird","subtitle":"Beetle","details":"A yellow ladybird whose fourteen black spots often merge into shapes like anchors, common on low plants across Europe and Asia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%28MHNT%29%20Propylea%20quatuordecimpunctata%20on%20Hypericum%20perforatum.jpg?width=1024"}]});
